// --- Prototype wiring
function interact(id, targetId, action, transition){
  const node = n(id);
  if(!node) return id+':missing';
  node.reactions = [{
    trigger: {type: 'ON_CLICK'},
    actions: [{
      type: 'NODE',
      destinationId: targetId,
      navigation: action || 'NAVIGATE',
      transition: transition === false ? null : {type:'DISSOLVE', easing:{type:'EASE_OUT'}, duration:0.25},
      preserveScrollPosition: false
    }]
  }];
  return id+':ok';
}
