function dump(id){
  const n=figma.getNodeById(id); if(!n) return {id, missing:true};
  function d(x, depth){
    const o={t:x.type, n:x.name, w:Math.round(x.width), h:Math.round(x.height), x:Math.round(x.x), y:Math.round(x.y)};
    try{ if(Array.isArray(x.fills)&&x.fills.length) o.f = x.fills.map(f=>f.type==='SOLID'? 'solid': f.type); }catch(e){}
    try{ if(Array.isArray(x.strokes)&&x.strokes.length) o.s = x.strokes.length; }catch(e){}
    if(depth<3 && x.children) o.c = x.children.map(c=>d(c,depth+1));
    return o;
  }
  return d(n,0);
}
