const page = figma.root.children.find(p => p.id === '5:2');
await figma.setCurrentPageAsync(page);
const log=[];
const screenIds=['17:188','17:417','17:673'];
let fixed=0, kept=0;
screenIds.forEach(sid=>{
  const f=figma.getNodeById(sid); if(!f) return;
  f.children.filter(c=>/^Product Card/.test(c.name) || /^Product Row/.test(c.name)).forEach(card=>{
    const ph=card.findOne(x=>x.name==='Photo');
    if(!ph) return;
    let hasImage=false;
    try{ hasImage = Array.isArray(ph.fills) && ph.fills.some(x=>x.type==='IMAGE'); }catch(e){}
    const label=ph.findOne(x=>x.name==='No photo' && x.type==='TEXT');
    const glyph=ph.findOne(x=>x.type==='INSTANCE' && /Icon_Cart/.test(x.name));
    if(hasImage){
      if(label) label.visible=false;
      if(glyph) glyph.visible=false;
      fixed++;
    } else {
      kept++;
    }
  });
  log.push(sid+' processed');
});
return JSON.stringify({fixed:fixed, keptFallback:kept, log:log});

